const $=s=>document.querySelector(s),file=$('#file'),drop=$('#drop'),img=$('#image'),canvas=$('#canvas'),message=$('#message'),ctx=canvas.getContext('2d');let currentURL=null,source=null,prepared=null,view='result',timer=0,revision=0,baseName='白模';
function cutout(src){const w=src.width,h=src.height,d=src.data,n=w*h,a=new Uint8ClampedArray(n);let own=false;for(let i=0;i<n;i++){a[i]=d[i*4+3];if(a[i]<250)own=true;}if(own)return a;const c=[0,0,0];for(const i of [0,w-1,n-w,n-1])for(let k=0;k<3;k++)c[k]+=d[i*4+k]/4;const near=i=>Math.max(Math.abs(d[i*4]-c[0]),Math.abs(d[i*4+1]-c[1]),Math.abs(d[i*4+2]-c[2]))<26,bg=new Uint8Array(n),q=new Int32Array(n);let head=0,tail=0;const push=i=>{if(!bg[i]&&near(i)){bg[i]=1;q[tail++]=i;}};for(let x=0;x<w;x++){push(x);push(n-w+x);}for(let y=0;y<h;y++){push(y*w);push(y*w+w-1);}while(head<tail){const i=q[head++],x=i%w;if(x>0)push(i-1);if(x<w-1)push(i+1);if(i>=w)push(i-w);if(i<n-w)push(i+w);}if(tail>n*.97)return a;for(let y=0;y<h;y++)for(let x=0;x<w;x++){let s=0,m=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const xx=x+dx,yy=y+dy;if(xx<0||yy<0||xx>=w||yy>=h)continue;s+=bg[yy*w+xx];m++;}a[y*w+x]=255*(1-s/m);}return a;}
function show(which){view=which;img.hidden=!source||which!=='original';canvas.hidden=!source||which!=='result';$('#original').classList.toggle('active',which==='original');$('#result').classList.toggle('active',which==='result');}
function options(){return {style:$('#style').value,line:+$('#line').value,shade:+$('#shade').value,smooth:+$('#smooth').value,glow:+$('#glow').value,body:+$('#body').value,color:+$('#color').value};}
function update(){if(!source)return;clearTimeout(timer);message.textContent='正在本地处理…';timer=setTimeout(()=>{try{const o=options();if(!prepared||prepared.smooth!==o.smooth){prepared=WhiteFilter.prepare(source.data,source.width,source.height,o.smooth);prepared.smooth=o.smooth;}const px=WhiteFilter.render(prepared,o);if(!source.mask)source.mask=baseMask();for(let i=0;i<source.mask.length;i++)px[i*4+3]=source.mask[i];frame=new ImageData(px,source.width,source.height);ctx.putImageData(frame,0,0);$('#download').disabled=false;show('result');message.textContent='效果已生成，可调节色彩与柔光，或切换原图对比。';}catch(e){message.textContent='处理失败，请尝试尺寸较小的图片。';}},35);}
function acceptImage(test,name){const scale=Math.min(1,2400/Math.max(test.naturalWidth||test.width,test.naturalHeight||test.height));canvas.width=Math.max(1,Math.round((test.naturalWidth||test.width)*scale));canvas.height=Math.max(1,Math.round((test.naturalHeight||test.height)*scale));ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(test,0,0,canvas.width,canvas.height);source=ctx.getImageData(0,0,canvas.width,canvas.height);prepared=null;undo.length=0;$('#undo').disabled=true;img.src=test.src;$('#empty').hidden=true;$('#filename').textContent=name;$('#dimensions').textContent=canvas.width+' × '+canvas.height+' px';baseName=name.replace(/\.[^.]+$/,'');show('result');update();}
function load(f){if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)){message.textContent='请选择 JPG、PNG 或 WebP 图片。';return;}if(f.size>20*1024*1024){message.textContent='图片超过 20 MB，请压缩后再上传。';return;}const id=++revision,url=URL.createObjectURL(f),test=new Image();message.textContent='正在读取图片…';test.onload=()=>{if(id!==revision){URL.revokeObjectURL(url);return;}try{acceptImage(test,f.name);if(currentURL)URL.revokeObjectURL(currentURL);currentURL=url;}catch(e){URL.revokeObjectURL(url);message.textContent='图片无法处理，请换一张较小的图片。';}};test.onerror=()=>{URL.revokeObjectURL(url);if(id===revision)message.textContent='图片无法读取，请换一张图片。';};test.src=url;}
file.onchange=()=>{load(file.files[0]);file.value='';};for(const name of ['dragenter','dragover'])drop.addEventListener(name,e=>{e.preventDefault();drop.classList.add('over');});for(const name of ['dragleave','drop'])drop.addEventListener(name,e=>{e.preventDefault();drop.classList.remove('over');});drop.addEventListener('drop',e=>load(e.dataTransfer.files[0]));$('#original').onclick=()=>show('original');$('#result').onclick=()=>show('result');for(const id of ['line','shade','smooth','glow','body','color'])$('#'+id).oninput=()=>{$('#'+id+'Value').textContent=$('#'+id).value;update();};const effectNotes={ascii:'图1：黑底彩色ASCII字符画。线条深浅调字符密度；保留黑底请取消「透明底导出」。',iceblue:'图2：复古杂志冰蓝调，保留原有透明材质反光。',scanner:'图3：青蓝洋红伪彩、扫描线、颗粒与技术标记；非真实扫描。',frost:'图4：高亮冰青透光与紫色暗部；不推断内部骨骼。',xrayblue:'图5上：冷蓝玻璃透视模拟，不生成原图没有的内部结构。',xraydark:'图5下：黑底银白发光轮廓，模拟X光视觉。保留黑底请取消「透明底导出」。',vision:'图6：依据图像边缘叠加特征框，非物体识别结果。',redconstruct:'图7：红黑色阶与青色错位线。完整爆炸结构仍需单独设计。'};$('#style').onchange=()=>{const mode=$('#style').value;$('#effectHelp').textContent=effectNotes[mode]||'保留实物质感，调节色彩、阴影与柔光。';update();};$('#cutout').onchange=()=>{if(source){source.mask=null;undo.length=0;$('#undo').disabled=true;}update();};
$('#download').onclick=()=>canvas.toBlob(blob=>{if(!blob){message.textContent='下载失败，请重试。';return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=baseName+'-'+$('#style').selectedOptions[0].textContent.split(' · ')[0]+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);},'image/png');
$('#demo').onclick=()=>{const id=++revision,test=new Image();test.onload=()=>{if(id!==revision)return;if(currentURL){URL.revokeObjectURL(currentURL);currentURL=null;}acceptImage(test,WHITEFORM_APPLE.name);};test.onerror=()=>message.textContent='苹果示例无法读取，请手动导入示例原图。';test.src=WHITEFORM_APPLE.src;};

// ── Manual cut-out: a mask she edits by hand (255 = keep). The wand clears the patch of one colour she clicks, the
// eraser and the restore brush paint it; the filter is not run again for these, only the alpha is redrawn.
let frame=null,tool='none',stroke=false,last=null;const undo=[];
function baseMask(){return $('#cutout').checked?cutout(source):new Uint8ClampedArray(source.width*source.height).fill(255);}
function paintMask(x0,y0,x1,y1){const w=source.width;x0=Math.max(0,Math.floor(x0));y0=Math.max(0,Math.floor(y0));x1=Math.min(w,Math.ceil(x1));y1=Math.min(source.height,Math.ceil(y1));if(x1<=x0||y1<=y0)return;const d=frame.data,m=source.mask;for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++)d[(y*w+x)*4+3]=m[y*w+x];ctx.putImageData(frame,0,0,x0,y0,x1-x0,y1-y0);}
function remember(){undo.push(source.mask.slice());if(undo.length>12)undo.shift();$('#undo').disabled=false;}
function point(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height];}
function brushRadius(){const r=canvas.getBoundingClientRect();return Math.max(1.5,+$('#brush').value/2*canvas.width/r.width);}
function dab(x,y){const r=brushRadius(),m=source.mask,w=source.width,h=source.height,keep=tool==='restore';for(let yy=Math.max(0,Math.floor(y-r));yy<Math.min(h,y+r+1);yy++)for(let xx=Math.max(0,Math.floor(x-r));xx<Math.min(w,x+r+1);xx++){const dd=Math.hypot(xx-x,yy-y)/r;if(dd>=1)continue;const soft=Math.min(1,(1-dd)*4),i=yy*w+xx;m[i]=keep?Math.max(m[i],255*soft):Math.min(m[i],255*(1-soft));}paintMask(x-r,y-r,x+r+1,y+r+1);}
function wand(x,y){x=Math.floor(x);y=Math.floor(y);const w=source.width,h=source.height,d=source.data,n=w*h,tol=+$('#tolerance').value;if(x<0||y<0||x>=w||y>=h)return;const ch=(i,k)=>{const a=d[i*4+3]/255;return d[i*4+k]*a+255*(1-a);},s=y*w+x,c0=ch(s,0),c1=ch(s,1),c2=ch(s,2),hit=new Uint8Array(n),q=new Int32Array(n);let head=0,tail=0,x0=x,x1=x,y0=y,y1=y;hit[s]=1;q[tail++]=s;const push=i=>{if(!hit[i]&&Math.abs(ch(i,0)-c0)<=tol&&Math.abs(ch(i,1)-c1)<=tol&&Math.abs(ch(i,2)-c2)<=tol){hit[i]=1;q[tail++]=i;}};while(head<tail){const i=q[head++],px=i%w,py=(i/w)|0;if(px<x0)x0=px;if(px>x1)x1=px;if(py<y0)y0=py;if(py>y1)y1=py;if(px>0)push(i-1);if(px<w-1)push(i+1);if(py>0)push(i-w);if(py<h-1)push(i+w);}const m=source.mask;for(let yy=Math.max(0,y0-1);yy<=Math.min(h-1,y1+1);yy++)for(let xx=Math.max(0,x0-1);xx<=Math.min(w-1,x1+1);xx++){let sum=0,cnt=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const ax=xx+dx,ay=yy+dy;if(ax<0||ay<0||ax>=w||ay>=h)continue;sum+=hit[ay*w+ax];cnt++;}if(sum){const i=yy*w+xx;m[i]=Math.min(m[i],255*(1-sum/cnt));}}paintMask(x0-1,y0-1,x1+2,y1+2);}
for(const b of document.querySelectorAll('#tools button'))b.onclick=()=>{tool=b.dataset.tool;for(const o of document.querySelectorAll('#tools button'))o.classList.toggle('active',o===b);canvas.style.touchAction=tool==='none'?'':'none';canvas.style.cursor=tool==='none'?'':'crosshair';if(tool!=='none'&&source)show('result');message.textContent=tool==='wand'?'魔棒：点一下要去掉的那块颜色（比如没抠干净的白底）。去多了就调小容差，再撤销重点。':tool==='erase'?'橡皮擦：在图上涂，涂到的地方变透明。':tool==='restore'?'涂回来：把擦多了的地方涂回来。':'';};
canvas.addEventListener('pointerdown',e=>{if(tool==='none'||!source||!frame||!source.mask)return;e.preventDefault();remember();const [x,y]=point(e);if(tool==='wand'){wand(x,y);return;}canvas.setPointerCapture(e.pointerId);stroke=true;last=[x,y];dab(x,y);});
canvas.addEventListener('pointermove',e=>{if(!stroke)return;const [x,y]=point(e),step=Math.max(1,brushRadius()/2),len=Math.hypot(x-last[0],y-last[1]),k=Math.max(1,Math.ceil(len/step));for(let i=1;i<=k;i++)dab(last[0]+(x-last[0])*i/k,last[1]+(y-last[1])*i/k);last=[x,y];});
for(const name of ['pointerup','pointercancel'])canvas.addEventListener(name,()=>{stroke=false;});
$('#undo').onclick=()=>{if(!undo.length||!source)return;source.mask=undo.pop();$('#undo').disabled=!undo.length;paintMask(0,0,source.width,source.height);};
$('#resetcut').onclick=()=>{if(!source||!source.mask)return;remember();source.mask=baseMask();paintMask(0,0,source.width,source.height);};
for(const id of ['tolerance','brush'])$('#'+id).oninput=()=>{$('#'+id+'Value').textContent=$('#'+id).value;};
